import React from "react";
function LeftSection({imageURL, pproductName, productDescription, tryDemo, learnmore, googlePlay,appStore}) {
  return (
    <>
      <div className="container">
        <div className="row">
        <div className="col-6 p-3">
            <img src="/media/images/images/Kite.png">
        </img>
        </div>
        <div className="col-6 p-3"></div>
      </div>
      </div>
    </>
  );
}
export default LeftSection;
